def is_valid_schedule(shifts):
    ordered = sorted(shifts)
    total = 0
    for start, end in ordered:
        if not (0 <= start < end <= 1440):
            return False
        if not 30 <= end - start <= 240:
            return False
        total += end - start
    for (s1, e1), (s2, e2) in zip(ordered, ordered[1:]):
        if s2 - e1 < 15:
            return False
    return total <= 600
